QQ.EXAMPLES = {
 "01_bits": {
  "file": "examples/01_bits.py",
  "code": "\"\"\"Level 1, BITS: n bits have 2**n patterns, but hold one.\n\nRun: python examples/01_bits.py\n\"\"\"\nfrom itertools import product\n\nfor n in range(1, 5):\n    patterns = [\"\".join(p) for p in product(\"01\", repeat=n)]\n    print(n, \"bits:\", len(patterns), \"patterns:\", patterns[:8])\n    assert len(patterns) == 2**n\n\n# a classical register holds exactly one of them at a time\nregister = \"101\"\nprint(\"the register now holds only\", register)\nprint(\"a byte has\", 2**8, \"patterns\")\nassert 2**8 == 256\n"
 },
 "02_binary": {
  "file": "examples/02_binary.py",
  "code": "\"\"\"Level 2, BINARY NUMBERS: place values 1, 2, 4, 8, ...\n\nRun: python examples/02_binary.py\n\"\"\"\nfor text in [\"101\", \"1011\", \"1111\"]:\n    value = int(text, 2)\n    places = \" + \".join(\n        f\"{d}x{2**i}\" for i, d in enumerate(reversed(text)))\n    print(text, \"=\", places, \"=\", value)\n\nassert int(\"1011\", 2) == 11\nassert format(5, \"03b\") == \"101\"\n\n# 4 bits count from 0 to 15\nfor n in range(16):\n    print(format(n, \"04b\"), n)\n\n# a ket label is a number: |101> is basis state number 5\nprint(\"|101> is basis state\", int(\"101\", 2))\n"
 },
 "03_gates": {
  "file": "examples/03_gates.py",
  "code": "\"\"\"Level 3, LOGIC GATES: truth tables, NAND builds everything.\n\nRun: python examples/03_gates.py\n\"\"\"\ndef NAND(a, b):\n    return 1 - (a & b)\n\n# NOT, AND, OR and XOR from NAND alone\ndef NOT(a):\n    return NAND(a, a)\n\ndef AND(a, b):\n    return NOT(NAND(a, b))\n\ndef OR(a, b):\n    return NAND(NOT(a), NOT(b))\n\ndef XOR(a, b):\n    c = NAND(a, b)\n    return NAND(NAND(a, c), NAND(b, c))\n\nprint(\"A B | AND OR XOR\")\nfor a in (0, 1):\n    for b in (0, 1):\n        print(a, b, \"|\", AND(a, b), OR(a, b), XOR(a, b))\n        assert AND(a, b) == (a & b)\n        assert OR(a, b) == (a | b)\n        assert XOR(a, b) == (a ^ b)\n\n# a half adder: XOR is the sum digit, AND the carry\nfor a in (0, 1):\n    for b in (0, 1):\n        carry, total = AND(a, b), XOR(a, b)\n        print(f\"{a} + {b} = {carry}{total} (binary)\")\n        assert 2 * carry + total == a + b\n"
 },
 "04_reversible": {
  "file": "examples/04_reversible.py",
  "code": "\"\"\"Level 4, REVERSIBLE COMPUTING: Toffoli keeps information.\n\nRun: python examples/04_reversible.py\n\"\"\"\nfrom itertools import product\nfrom math import log\n\nfrom qiskit import QuantumCircuit\nfrom qiskit.quantum_info import Operator\n\n\ndef toffoli(a, b, c):\n    return a, b, c ^ (a & b)\n\n# reversible: 8 different inputs give 8 different outputs\nouts = {toffoli(*bits) for bits in product((0, 1), repeat=3)}\nassert len(outs) == 8\n# with c = 0 the third bit is a AND b\nfor a, b in product((0, 1), repeat=2):\n    assert toffoli(a, b, 0)[2] == (a & b)\n# and running it twice undoes it\nfor bits in product((0, 1), repeat=3):\n    assert toffoli(*toffoli(*bits)) == bits\n\n# AND is not reversible: three inputs give the output 0\nprint(\"AND inputs giving 0:\",\n      [ab for ab in product((0, 1), repeat=2)\n       if ab[0] & ab[1] == 0])\n\n# the same gate in Qiskit is a permutation matrix\nqc = QuantumCircuit(3)\nqc.ccx(0, 1, 2)\nU = Operator(qc)\nprint(U.data.real.astype(int))\nassert U.is_unitary()\n\n# Landauer: erasing a bit costs at least kT ln 2\nk = 1.380649e-23  # Boltzmann constant, J/K (exact in SI)\nprint(\"kT ln 2 at 300 K =\", k * 300 * log(2), \"joule\")\n"
 },
 "05_probability": {
  "file": "examples/05_probability.py",
  "code": "\"\"\"Level 5, PROBABILITY: chances, products, many shots.\n\nRun: python examples/05_probability.py\n\"\"\"\nfrom fractions import Fraction\n\nimport numpy as np\n\n# two fair coins: HH, HT, TH, TT are equally likely\np_both = Fraction(1, 2) * Fraction(1, 2)\nprint(\"P(both heads) =\", p_both)\nassert p_both == Fraction(1, 4)\n\n# the complement rule\nprint(\"P(not a 6) =\", 1 - Fraction(1, 6))\n\n# the law of large numbers: shares approach probabilities\nrng = np.random.default_rng(seed=7)\nfor shots in (10, 100, 1000, 100000):\n    hits = (rng.random(shots) < 0.25).sum()\n    print(f\"{shots:6d} shots: share {hits / shots:.3f}\")\n\nhits = (rng.random(100000) < 0.25).sum()\nassert abs(hits / 100000 - 0.25) < 0.01\n"
 },
 "06_vectors": {
  "file": "examples/06_vectors.py",
  "code": "\"\"\"Level 6, VECTORS: add, scale, length, basis.\n\nRun: python examples/06_vectors.py\n\"\"\"\nimport numpy as np\n\nv = np.array([3.0, 4.0])\nprint(\"length of (3, 4):\", np.linalg.norm(v))\nassert np.isclose(np.linalg.norm(v), 5)\n\nprint(\"(1,2) + (3,0) =\", np.array([1, 2]) + np.array([3, 0]))\nprint(\"2 x (1,2) =\", 2 * np.array([1, 2]))\n\n# every vector is a mix of the basis vectors e0, e1\ne0, e1 = np.array([1, 0]), np.array([0, 1])\na, b = 0.6, 0.8\nw = a * e0 + b * e1\nprint(\"0.6 e0 + 0.8 e1 =\", w, \"length\", np.linalg.norm(w))\nassert np.isclose(np.linalg.norm(w), 1)  # a unit vector\n"
 },
 "07_matrices": {
  "file": "examples/07_matrices.py",
  "code": "\"\"\"Level 7, MATRICES: a matrix moves vectors; order matters.\n\nRun: python examples/07_matrices.py\n\"\"\"\nimport numpy as np\n\nX = np.array([[0, 1], [1, 0]])\nZ = np.array([[1, 0], [0, -1]])\nv = np.array([2, 5])\n\nprint(\"X v =\", X @ v)  # swaps the two numbers\nassert (X @ v == [5, 2]).all()\n\nprint(\"[2 0; 0 3] (1, 1) =\", np.diag([2, 3]) @ [1, 1])\n\n# A B v = A (B v): B acts first\nassert (X @ Z @ v == X @ (Z @ v)).all()\n\n# order matters: XZ is not ZX (here XZ = -ZX)\nprint(\"XZ =\\n\", X @ Z, \"\\nZX =\\n\", Z @ X)\nassert not np.array_equal(X @ Z, Z @ X)\nassert np.array_equal(X @ Z, -(Z @ X))\n\nI = np.eye(2)\nassert np.array_equal(X @ X, I)  # X undoes itself\n"
 },
 "08_complex": {
  "file": "examples/08_complex.py",
  "code": "\"\"\"Level 8, COMPLEX NUMBERS: i*i = -1, size, conjugate.\n\nPython writes i as 1j.\nRun: python examples/08_complex.py\n\"\"\"\nz = 3 + 4j\nprint(\"z =\", z, \" |z| =\", abs(z), \" z* =\", z.conjugate())\nassert abs(z) == 5\n\nassert 1j * 1j == -1\nassert (1j) ** 4 == 1\nprint(\"(1+2i) + (3-i) =\", (1 + 2j) + (3 - 1j))\nprint(\"(1+i)(1-i) =\", (1 + 1j) * (1 - 1j))\nassert (1 + 1j) * (1 - 1j) == 2\n\n# z times its conjugate is |z|^2, a real number\nprint(\"z z* =\", z * z.conjugate())\nassert z * z.conjugate() == abs(z) ** 2\n"
 },
 "09_euler": {
  "file": "examples/09_euler.py",
  "code": "\"\"\"Level 9, PHASE AND EULER: e^(i theta) = cos + i sin.\n\nRun: python examples/09_euler.py\n\"\"\"\nimport cmath\nimport math\n\nfor theta in (0, math.pi / 4, math.pi / 2, math.pi):\n    z = cmath.exp(1j * theta)\n    print(f\"theta={theta:.3f}  e^(i theta)={z:.3f}\",\n          f\"|z|={abs(z):.3f}\")\n    assert math.isclose(abs(z), 1)\n    euler = math.cos(theta) + 1j * math.sin(theta)\n    assert cmath.isclose(z, euler)\n\n# Euler's identity: e^(i pi) = -1\nassert cmath.isclose(cmath.exp(1j * math.pi), -1)\n# multiplying adds angles: two quarter turns are a half turn\nq = cmath.exp(1j * math.pi / 2)\nassert cmath.isclose(q * q, -1)\n\n# a phase never changes a probability |a|^2\na = 0.6\nfor theta in (0.3, 1.0, 2.5):\n    b = cmath.exp(1j * theta) * a\n    assert math.isclose(abs(b) ** 2, a**2)\nprint(\"phases keep probabilities\")\n"
 },
 "10_inner": {
  "file": "examples/10_inner.py",
  "code": "\"\"\"Level 10, INNER PRODUCTS: <a|b> conjugates the bra.\n\nnp.vdot(a, b) conjugates a, so it is exactly <a|b>.\nRun: python examples/10_inner.py\n\"\"\"\nimport numpy as np\n\ns = 1 / np.sqrt(2)\nket0 = np.array([1, 0])\nket1 = np.array([0, 1])\nplus = np.array([s, s])\nminus = np.array([s, -s])\nplus_i = np.array([s, 1j * s])\n\nprint(\"<0|1> =\", np.vdot(ket0, ket1))\nprint(\"<+|-> =\", np.vdot(plus, minus))\nprint(\"<+|+> =\", np.vdot(plus, plus))\nassert np.isclose(np.vdot(ket0, ket1), 0)\nassert np.isclose(np.vdot(plus, minus), 0)\nassert np.isclose(np.vdot(plus_i, plus_i), 1)\n\n# chance to find |+> as |0>: |<0|+>|^2 = 1/2\np = abs(np.vdot(ket0, plus)) ** 2\nprint(\"|<0|+>|^2 =\", p)\nassert np.isclose(p, 0.5)\n\n# without the conjugate the length of |+i> would come out 0\nprint(\"wrong, no conjugate:\", plus_i @ plus_i)\n"
 },
 "11_tensor": {
  "file": "examples/11_tensor.py",
  "code": "\"\"\"Level 11, TENSOR PRODUCTS: np.kron joins systems.\n\nnp.kron(a, b) puts a on the LEFT digit, like this game.\nRun: python examples/11_tensor.py\n\"\"\"\nimport numpy as np\n\nket0, ket1 = np.array([1, 0]), np.array([0, 1])\nprint(\"|0> x |1> =\", np.kron(ket0, ket1))  # |01>\nprint(\"|1> x |0> =\", np.kron(ket1, ket0))  # |10>\nassert (np.kron(ket1, ket0) == [0, 0, 1, 0]).all()\n\n# sizes multiply: 10 qubits need 2**10 numbers\nstate = ket0\nfor _ in range(9):\n    state = np.kron(state, ket0)\nprint(\"10 qubits:\", state.size, \"amplitudes\")\nassert state.size == 1024\n\n\ndef is_product(psi):\n    \"\"\"A 2-qubit state is a product exactly when its 2x2\n    reshape has rank 1 (one Schmidt coefficient).\"\"\"\n    return np.linalg.matrix_rank(psi.reshape(2, 2)) == 1\n\n\ns = 1 / np.sqrt(2)\nplus = np.array([s, s])\nbell = np.array([s, 0, 0, s])\nprint(\"|+>|+> is a product:\", is_product(np.kron(plus, plus)))\nprint(\"Bell state is a product:\", is_product(bell))\nassert is_product(np.kron(plus, ket1))\nassert not is_product(bell)\n\n# matrices too: X on the first qubit, nothing on the second\nX, I = np.array([[0, 1], [1, 0]]), np.eye(2)\nprint(\"(X x I)|00> =\", np.kron(X, I) @ np.kron(ket0, ket0))\n"
 },
 "12_unitary": {
  "file": "examples/12_unitary.py",
  "code": "\"\"\"Level 12, UNITARY MATRICES: U-dagger U = I.\n\nRun: python examples/12_unitary.py\n\"\"\"\nimport numpy as np\nfrom qiskit.circuit.library import HGate, SGate, XGate\nfrom qiskit.quantum_info import Operator\n\n\ndef dagger(U):\n    return U.conj().T\n\n\ndef is_unitary(U):\n    return np.allclose(dagger(U) @ U, np.eye(len(U)))\n\n\nH = np.array([[1, 1], [1, -1]]) / np.sqrt(2)\nS = np.array([[1, 0], [0, 1j]])\nprint(\"H unitary:\", is_unitary(H), \" S unitary:\", is_unitary(S))\nassert is_unitary(H) and is_unitary(S)\nassert not is_unitary(np.diag([1, 2]))  # it stretches\n\n# the inverse of a unitary is its dagger\nassert np.allclose(H @ H, np.eye(2))  # H undoes itself\n# S-dagger undoes S\nassert np.allclose(S @ dagger(S), np.eye(2))\n\n# Hermitian: U equals its dagger. H is, S is not.\nassert np.allclose(H, dagger(H))\nassert not np.allclose(S, dagger(S))\n\n# Qiskit knows the same matrices\nfor gate in (XGate(), HGate(), SGate()):\n    print(gate.name, Operator(gate).is_unitary())\n    assert Operator(gate).is_unitary()\n"
 },
 "13_qubit": {
  "file": "examples/13_qubit.py",
  "code": "\"\"\"Level 13, THE QUBIT: a unit vector of two amplitudes.\n\nRun: python examples/13_qubit.py\n\"\"\"\nfrom qiskit.quantum_info import Statevector\n\npsi = Statevector([0.6, 0.8])\nprint(psi)\nprint(\"valid (length 1):\", psi.is_valid())\nprint(\"chances:\", psi.probabilities())\nassert psi.is_valid()\n\nfor amps in ([0.5, 0.5], [1, 1], [0.9, 0.9]):\n    print(amps, \"valid:\", Statevector(amps).is_valid())\n    assert not Statevector(amps).is_valid()\n\n# complex amplitudes are fine too\ns = 2 ** -0.5\nassert Statevector([s, 1j * s]).is_valid()\n"
 },
 "14_measure": {
  "file": "examples/14_measure.py",
  "code": "\"\"\"Level 14, MEASUREMENT: the Born rule and shots.\n\nRun: python examples/14_measure.py\n\"\"\"\nfrom qiskit import QuantumCircuit\nfrom qiskit.primitives import StatevectorSampler\nfrom qiskit.quantum_info import Statevector\n\n# P(1) = |0.8|^2 for 0.6|0> + 0.8|1>\npsi = Statevector([0.6, 0.8])\nprint(\"P(0), P(1) =\", psi.probabilities())\n\n# |+> measured 1024 times: roughly half and half\nqc = QuantumCircuit(1)\nqc.h(0)\nqc.measure_all()\nsampler = StatevectorSampler(seed=1234)\nresult = sampler.run([qc], shots=1024).result()\ncounts = result[0].data.meas.get_counts()\nprint(\"counts for |+>:\", counts)\nassert set(counts) == {\"0\", \"1\"}\nassert abs(counts[\"0\"] - 512) < 80\n\n# a measured qubit stays put: measure twice, same answer\nqc2 = QuantumCircuit(1, 2)\nqc2.h(0)\nqc2.measure(0, 0)\nqc2.measure(0, 1)\nres = StatevectorSampler(seed=5).run([qc2], shots=200)\ntwice = res.result()[0].data.c.get_counts()\nprint(\"measured twice:\", twice)\nassert set(twice) <= {\"00\", \"11\"}\n\n# a global sign changes nothing\nminus0 = Statevector([-1, 0])\nassert minus0.equiv(Statevector([1, 0]))\n"
 },
 "15_xgate": {
  "file": "examples/15_xgate.py",
  "code": "\"\"\"Level 15, THE X GATE: the quantum NOT.\n\nRun: python examples/15_xgate.py\n\"\"\"\nfrom qiskit import QuantumCircuit\nfrom qiskit.quantum_info import Operator, Statevector\n\nqc = QuantumCircuit(1)\nqc.x(0)\nprint(qc.draw())\nstate = Statevector(qc)\nprint(\"X|0> =\", state)\nassert state.equiv(Statevector.from_label(\"1\"))\n\nprint(\"X =\\n\", Operator(qc).data.real)\n\n# X swaps the amplitudes of any state\npsi = Statevector([0.6, 0.8])\nprint(\"X(0.6|0>+0.8|1>) =\", psi.evolve(qc))\nassert psi.evolve(qc).equiv(Statevector([0.8, 0.6]))\n\n# X twice is the identity\ntwice = QuantumCircuit(1)\ntwice.x(0)\ntwice.x(0)\nassert Operator(twice).equiv(Operator(QuantumCircuit(1)))\n"
 },
 "16_hadamard": {
  "file": "examples/16_hadamard.py",
  "code": "\"\"\"Level 16, SUPERPOSITION: H|0> = |+>, H|1> = |->.\n\nRun: python examples/16_hadamard.py\n\"\"\"\nfrom qiskit import QuantumCircuit\nfrom qiskit.quantum_info import Operator, Statevector\n\nplus = QuantumCircuit(1)\nplus.h(0)\nprint(\"H|0> =\", Statevector(plus))\nassert Statevector(plus).equiv(Statevector.from_label(\"+\"))\n\nminus = QuantumCircuit(1)\nminus.x(0)\nminus.h(0)\nprint(\"H|1> =\", Statevector(minus))\nassert Statevector(minus).equiv(Statevector.from_label(\"-\"))\n\nprint(\"H =\\n\", Operator(plus).data.real.round(3))\n# both are 50/50 coins\nfor qc in (plus, minus):\n    print(Statevector(qc).probabilities_dict())\n"
 },
 "17_interference": {
  "file": "examples/17_interference.py",
  "code": "\"\"\"Level 17, INTERFERENCE: H H |0> = |0>, path by path.\n\nRun: python examples/17_interference.py\n\"\"\"\nimport numpy as np\nfrom qiskit import QuantumCircuit\nfrom qiskit.quantum_info import Statevector\n\nH = np.array([[1, 1], [1, -1]]) / np.sqrt(2)\n\n# add up every path |0> -> |m> -> |k>: amplitude H[k,m]*H[m,0]\nfor k in (0, 1):\n    paths = [H[k, m] * H[m, 0] for m in (0, 1)]\n    print(f\"into |{k}>: paths {np.round(paths, 2)} sum\",\n          round(sum(paths), 2))\n# |1> gets +1/2 and -1/2: they cancel\nassert np.isclose(sum(H[1, m] * H[m, 0] for m in (0, 1)), 0)\n\nqc = QuantumCircuit(1)\nqc.h(0)\nqc.h(0)\nprint(\"H H |0> =\", Statevector(qc))\nassert Statevector(qc).equiv(Statevector.from_label(\"0\"))\n"
 },
 "18_phase": {
  "file": "examples/18_phase.py",
  "code": "\"\"\"Level 18, PHASE: Z S T: HZH = X, SS = Z, TT = S.\n\nRun: python examples/18_phase.py\n\"\"\"\nfrom qiskit import QuantumCircuit\nfrom qiskit.quantum_info import Operator, Statevector\n\n\ndef op(*gates):\n    qc = QuantumCircuit(1)\n    for g in gates:\n        getattr(qc, g)(0)\n    return Operator(qc)\n\n\nassert op(\"h\", \"z\", \"h\").equiv(op(\"x\"))   # puzzle: no X gate\nassert op(\"s\", \"s\").equiv(op(\"z\"))\nassert op(\"t\", \"t\").equiv(op(\"s\"))\nprint(\"HZH = X, SS = Z, TT = S: all true\")\n\n# Z turns |+> into |->; the chances do not change\nplus = Statevector.from_label(\"+\")\nafter = plus.evolve(op(\"z\"))\nprint(plus.probabilities(), after.probabilities())\nassert after.equiv(Statevector.from_label(\"-\"))\n\n# diagonal gates commute, so S T S-dagger is just T\nassert op(\"s\", \"t\", \"sdg\").equiv(op(\"t\"))\n# Operator.equiv ignores a global phase: Z X Z = -X counts as X\nassert op(\"z\", \"x\", \"z\").equiv(op(\"x\"))\nprint(\"T =\\n\", op(\"t\").data.round(3))\n"
 },
 "19_bloch": {
  "file": "examples/19_bloch.py",
  "code": "\"\"\"Level 19, THE BLOCH SPHERE: (<X>, <Y>, <Z>) of a qubit.\n\nRun: python examples/19_bloch.py\n\"\"\"\nimport numpy as np\nfrom qiskit import QuantumCircuit\nfrom qiskit.quantum_info import SparsePauliOp, Statevector\n\n\ndef bloch(state):\n    return np.array([\n        state.expectation_value(SparsePauliOp(p)).real\n        for p in (\"X\", \"Y\", \"Z\")])\n\n\ncases = {\"|0>\": [], \"|1>\": [\"x\"], \"|+>\": [\"h\"],\n         \"|->\": [\"h\", \"z\"], \"|+i>\": [\"h\", \"s\"]}\nfor name, gates in cases.items():\n    qc = QuantumCircuit(1)\n    for g in gates:\n        getattr(qc, g)(0)\n    v = bloch(Statevector(qc))\n    print(f\"{name:5s} Bloch vector {np.round(v, 3)}\")\n\n# the puzzle: H then Z points the arrow left, to (-1, 0, 0)\nqc = QuantumCircuit(1)\nqc.h(0)\nqc.z(0)\nassert np.allclose(bloch(Statevector(qc)), [-1, 0, 0])\n\n# cos(t/2)|0> + e^(ip) sin(t/2)|1> sits at angles (t, p)\nt, p = 1.0, 0.5\npsi = Statevector([np.cos(t / 2),\n                   np.exp(1j * p) * np.sin(t / 2)])\nexpect = [np.sin(t) * np.cos(p), np.sin(t) * np.sin(p),\n          np.cos(t)]\nassert np.allclose(bloch(psi), expect)\n"
 },
 "20_bases": {
  "file": "examples/20_bases.py",
  "code": "\"\"\"Level 20, BASES AND ROTATIONS: measure in X, any angle.\n\nRun: python examples/20_bases.py\n\"\"\"\nimport numpy as np\nfrom qiskit import QuantumCircuit\nfrom qiskit.quantum_info import Operator, Statevector\nfrom qiskit.synthesis import OneQubitEulerDecomposer\n\n# measuring in the X basis: H first, then a normal reading\nqc = QuantumCircuit(1)\nqc.x(0)\nqc.h(0)      # the qubit is |->\nqc.h(0)      # turn the X basis into the Z basis\nprint(\"|-> read in the X basis:\",\n      Statevector(qc).probabilities())\nassert np.allclose(Statevector(qc).probabilities(), [0, 1])\n\n# RY(pi/2)|0> = |+>, RX(pi) = X up to a global phase\nry = QuantumCircuit(1)\nry.ry(np.pi / 2, 0)\nassert Statevector(ry).equiv(Statevector.from_label(\"+\"))\nrx = QuantumCircuit(1)\nrx.rx(np.pi, 0)\nx = QuantumCircuit(1)\nx.x(0)\nassert Operator(rx).equiv(Operator(x))\n\n# any one-qubit gate is RZ RY RZ (times a global phase)\nrng = np.random.default_rng(3)\na, b, c = rng.uniform(0, 2 * np.pi, 3)\ngate = QuantumCircuit(1)\ngate.rx(a, 0)\ngate.ry(b, 0)\ngate.rz(c, 0)\nzyz = OneQubitEulerDecomposer(\"ZYZ\")(Operator(gate))\nprint(zyz.draw())\nassert Operator(zyz).equiv(Operator(gate))\n"
 },
 "21_two": {
  "file": "examples/21_two.py",
  "code": "\"\"\"Level 21, TWO QUBITS: four amplitudes, and Qiskit's order.\n\nQiskit writes qubit 0 as the RIGHTMOST digit. This game, and\nnp.kron, write it on the LEFT.\nRun: python examples/21_two.py\n\"\"\"\nfrom qiskit import QuantumCircuit\nfrom qiskit.quantum_info import Statevector\n\nqc = QuantumCircuit(2)\nqc.x(0)\nqc.x(1)\nprint(\"X on both:\", Statevector(qc).probabilities_dict())\nassert Statevector(qc).probabilities_dict() == {\"11\": 1.0}\n\n# only qubit 0 flipped: Qiskit shows '01', the game |10>\none = QuantumCircuit(2)\none.x(0)\nprint(\"X on qubit 0, Qiskit order:\",\n      Statevector(one).probabilities_dict())\nflipped = Statevector(one).reverse_qargs()\nprint(\"same state in the game's order:\",\n      flipped.probabilities_dict())\nassert \"10\" in flipped.probabilities_dict()\n\n# a coin on each wire: all four results equally likely\ncoins = QuantumCircuit(2)\ncoins.h([0, 1])\nprobs = Statevector(coins).probabilities_dict()\nprint(probs)\nassert all(abs(p - 0.25) < 1e-9 for p in probs.values())\n"
 },
 "22_cnot": {
  "file": "examples/22_cnot.py",
  "code": "\"\"\"Level 22, CNOT: flip the target when the control is 1.\n\nRun: python examples/22_cnot.py\n\"\"\"\nfrom qiskit import QuantumCircuit\nfrom qiskit.quantum_info import Operator, Statevector\n\nprint(\"control q0, target q1 (written q0 q1, game order)\")\nfor c in (0, 1):\n    for t in (0, 1):\n        qc = QuantumCircuit(2)\n        if c:\n            qc.x(0)\n        if t:\n            qc.x(1)\n        qc.cx(0, 1)\n        # reverse_qargs: q0 becomes the left digit again\n        out = Statevector(qc).reverse_qargs()\n        (key,) = out.probabilities_dict(decimals=9)\n        print(f\"|{c}{t}> -> |{key}>\")\n        assert key == f\"{c}{t ^ c}\"\n\n# the puzzle: one X and one CNOT make |11>\nqc = QuantumCircuit(2)\nqc.x(0)\nqc.cx(0, 1)\nassert Statevector(qc).probabilities_dict() == {\"11\": 1.0}\n\n# as a matrix, in Qiskit's order of basis states\n# (|00>, |01>, |10>, |11> with qubit 0 on the right)\ncnot = QuantumCircuit(2)\ncnot.cx(0, 1)\nprint(Operator(cnot).data.real)\n"
 },
 "23_bell": {
  "file": "examples/23_bell.py",
  "code": "\"\"\"Level 23, ENTANGLEMENT: the Bell state (|00> + |11>)/sqrt2.\n\nRun: python examples/23_bell.py\n\"\"\"\nimport numpy as np\nfrom qiskit import QuantumCircuit\nfrom qiskit.primitives import StatevectorSampler\nfrom qiskit.quantum_info import Statevector, partial_trace\n\nbell = QuantumCircuit(2)\nbell.h(0)\nbell.cx(0, 1)\nprint(bell.draw())\nstate = Statevector(bell)\nprint(state)\ns = 1 / np.sqrt(2)\nassert state.equiv(Statevector([s, 0, 0, s]))\n\n# measure 1000 times: only 00 and 11, never 01 or 10\nbell.measure_all()\nres = StatevectorSampler(seed=11).run([bell], shots=1000)\ncounts = res.result()[0].data.meas.get_counts()\nprint(\"counts:\", counts)\nassert set(counts) == {\"00\", \"11\"}\n\n# each qubit alone is a perfectly random bit\none = partial_trace(state, [1])\nprint(\"qubit 0 alone:\\n\", np.round(one.data.real, 3))\nassert np.allclose(one.data, np.eye(2) / 2)\n"
 },
 "24_bell4": {
  "file": "examples/24_bell4.py",
  "code": "\"\"\"Level 24, ALL FOUR BELLS: four orthogonal entangled states.\n\nRun: python examples/24_bell4.py\n\"\"\"\nimport numpy as np\nfrom qiskit import QuantumCircuit\nfrom qiskit.quantum_info import Statevector\n\n\ndef bell(z, x):\n    \"\"\"Phi+ , then Z (sign) and X (flip) on qubit 0 / 1.\"\"\"\n    qc = QuantumCircuit(2)\n    qc.h(0)\n    if z:\n        qc.z(0)\n    if x:\n        qc.x(1)\n    qc.cx(0, 1)\n    # game order: q0 is the left digit\n    return Statevector(qc).reverse_qargs()\n\n\ns = 1 / np.sqrt(2)\nnames = {\"Phi+\": (0, 0), \"Phi-\": (1, 0),\n         \"Psi+\": (0, 1), \"Psi-\": (1, 1)}\nwant = {\"Phi+\": [s, 0, 0, s], \"Phi-\": [s, 0, 0, -s],\n        \"Psi+\": [0, s, s, 0], \"Psi-\": [0, s, -s, 0]}\nstates = {}\nfor name, (z, x) in names.items():\n    states[name] = bell(z, x)\n    print(name, np.round(states[name].data.real, 3))\n    assert states[name].equiv(Statevector(want[name]))\n\n# all four are orthogonal: one measurement tells them apart\nfor a in states:\n    for b in states:\n        overlap = abs(states[a].inner(states[b]))\n        assert np.isclose(overlap, 1.0 if a == b else 0.0)\nprint(\"all four are orthogonal\")\n"
 },
 "25_swap": {
  "file": "examples/25_swap.py",
  "code": "\"\"\"Level 25, SWAP: three alternating CNOTs swap two qubits.\n\nRun: python examples/25_swap.py\n\"\"\"\nfrom qiskit import QuantumCircuit\nfrom qiskit.quantum_info import Operator, Statevector\n\nthree = QuantumCircuit(2)\nthree.cx(0, 1)\nthree.cx(1, 0)\nthree.cx(0, 1)\nprint(three.draw())\n\nswap = QuantumCircuit(2)\nswap.swap(0, 1)\nassert Operator(three).equiv(Operator(swap))\nprint(\"CX CX CX = SWAP\")\n\n# the puzzle's start: H T on q0, X on q1\nprep = QuantumCircuit(2)\nprep.h(0)\nprep.t(0)\nprep.x(1)\nbefore = Statevector(prep)\nafter = before.evolve(three)\n# swapping = reading the qubits in the other order\nassert after.equiv(before.reverse_qargs())\n"
 },
 "26_nocloning": {
  "file": "examples/26_nocloning.py",
  "code": "\"\"\"Level 26, NO CLONING: CNOT copies 0 and 1, not |+>.\n\nRun: python examples/26_nocloning.py\n\"\"\"\nimport numpy as np\nfrom qiskit import QuantumCircuit\nfrom qiskit.quantum_info import Statevector, state_fidelity\n\nfor label in (\"0\", \"1\"):\n    qc = QuantumCircuit(2)\n    if label == \"1\":\n        qc.x(0)\n    qc.cx(0, 1)\n    print(f\"copy of |{label}>:\",\n          Statevector(qc).probabilities_dict())\n\n# the same circuit on |+>\nqc = QuantumCircuit(2)\nqc.h(0)\nqc.cx(0, 1)\ngot = Statevector(qc)\ncopy = Statevector.from_label(\"++\")  # what a cloner would give\ns = 1 / np.sqrt(2)\nprint(\"got:\", np.round(got.data.real, 3))\nprint(\"a true copy:\", np.round(copy.data.real, 3))\nassert got.equiv(Statevector([s, 0, 0, s]))  # a Bell state\nprint(\"fidelity with |++>:\", state_fidelity(got, copy))\nassert state_fidelity(got, copy) < 0.51\n"
 },
 "27_toffoli": {
  "file": "examples/27_toffoli.py",
  "code": "\"\"\"Level 27, TOFFOLI AND UNIVERSALITY: reversible AND, OR.\n\nRun: python examples/27_toffoli.py\n\"\"\"\nfrom itertools import product\n\nfrom qiskit import QuantumCircuit\nfrom qiskit.quantum_info import Statevector\n\n\ndef run(a, b, gate):\n    qc = QuantumCircuit(3)\n    if a:\n        qc.x(0)\n    if b:\n        qc.x(1)\n    gate(qc)\n    out = Statevector(qc).reverse_qargs()  # game order\n    (key,) = out.probabilities_dict(decimals=9)\n    return key\n\n\ndef AND(qc):\n    qc.ccx(0, 1, 2)\n\n\ndef OR(qc):  # A OR B = NOT(NOT A AND NOT B)\n    qc.x([0, 1])\n    qc.ccx(0, 1, 2)\n    qc.x(2)\n    qc.x([0, 1])\n\n\nfor a, b in product((0, 1), repeat=2):\n    k_and, k_or = run(a, b, AND), run(a, b, OR)\n    print(a, b, \"AND ->\", k_and, \" OR ->\", k_or)\n    assert k_and == f\"{a}{b}{a & b}\"\n    assert k_or == f\"{a}{b}{a | b}\"\n"
 },
 "28_chsh": {
  "file": "examples/28_chsh.py",
  "code": "\"\"\"Level 28, THE BELL TEST: CHSH, classical 2, quantum 2.83.\n\nRun: python examples/28_chsh.py\n\"\"\"\nfrom itertools import product\n\nimport numpy as np\nfrom qiskit import QuantumCircuit\nfrom qiskit.quantum_info import SparsePauliOp, Statevector\n\n# classical: try every fixed plan a(x), b(y)\nbest = 0\nfor a0, a1, b0, b1 in product((0, 1), repeat=4):\n    wins = sum(((a1 if x else a0) ^ (b1 if y else b0))\n               == (x & y) for x, y in product((0, 1), repeat=2))\n    best = max(best, wins / 4)\nprint(\"best classical win rate:\", best)\nassert best == 0.75\n\n# quantum: a Bell pair; Alice measures Z or X, Bob at 45 deg\nbell = QuantumCircuit(2)\nbell.h(0)\nbell.cx(0, 1)\nstate = Statevector(bell)\nr = 1 / np.sqrt(2)\nA = [SparsePauliOp(\"Z\"), SparsePauliOp(\"X\")]\nB = [SparsePauliOp([\"Z\", \"X\"], [r, r]),\n     SparsePauliOp([\"Z\", \"X\"], [r, -r])]\n\n\ndef corr(a, b):  # Qiskit order: Bob is qubit 1 (left)\n    return state.expectation_value(b ^ a).real\n\n\nS = corr(A[0], B[0]) + corr(A[0], B[1]) \\\n    + corr(A[1], B[0]) - corr(A[1], B[1])\nprint(\"CHSH value S =\", round(S, 4), \" 2*sqrt(2) =\",\n      round(2 * np.sqrt(2), 4))\nassert np.isclose(S, 2 * np.sqrt(2))\nwin = np.cos(np.pi / 8) ** 2\nprint(\"quantum win rate:\", round(win, 4))\nassert np.isclose(win, 0.5 + S / 8)\n"
 },
 "29_superdense": {
  "file": "examples/29_superdense.py",
  "code": "\"\"\"Level 29, SUPERDENSE CODING: two bits in one qubit.\n\nRun: python examples/29_superdense.py\n\"\"\"\nfrom qiskit import QuantumCircuit\nfrom qiskit.quantum_info import Statevector\n\n\ndef send(bits):\n    qc = QuantumCircuit(2)\n    qc.h(0)          # the shared Bell pair:\n    qc.cx(0, 1)      # q0 is Alice's, q1 is Bob's\n    first, second = bits\n    if second == \"1\":\n        qc.x(0)      # Alice touches only her qubit q0\n    if first == \"1\":\n        qc.z(0)\n    qc.cx(0, 1)      # Bob decodes\n    qc.h(0)\n    out = Statevector(qc).reverse_qargs()  # game order q0 q1\n    (key,) = out.probabilities_dict(decimals=9)\n    return key\n\n\nfor bits in (\"00\", \"01\", \"10\", \"11\"):\n    got = send(bits)\n    print(f\"Alice sends {bits}, Bob reads {got}\")\n    assert got == bits\n"
 },
 "30_teleport": {
  "file": "examples/30_teleport.py",
  "code": "\"\"\"Level 30, TELEPORTATION: with deferred measurement.\n\n\"Measure, then X / Z if the bit is 1\" is written as CNOT /\nCZ from the measured qubit, then measuring at the end.\nRun: python examples/30_teleport.py\n\"\"\"\nimport numpy as np\nfrom qiskit import QuantumCircuit\nfrom qiskit.quantum_info import Statevector, partial_trace\n\nrng = np.random.default_rng(42)\nfor trial in range(5):\n    theta = rng.uniform(0, np.pi)\n    phi = rng.uniform(0, 2 * np.pi)\n    psi = QuantumCircuit(1)\n    psi.ry(theta, 0)\n    psi.rz(phi, 0)\n\n    qc = QuantumCircuit(3)\n    qc.compose(psi, [0], inplace=True)  # |psi> on q0\n    qc.h(1)                             # Bell pair q1, q2\n    qc.cx(1, 2)\n    qc.cx(0, 1)                         # Alice\n    qc.h(0)\n    qc.cx(1, 2)                         # Bob's X fix\n    qc.cz(0, 2)                         # Bob's Z fix\n\n    bob = partial_trace(Statevector(qc), [0, 1])  # keep q2\n    want = Statevector(psi)\n    fidelity = np.real(want.data.conj() @ bob.data @ want.data)\n    print(f\"trial {trial}: fidelity {fidelity:.6f}\")\n    assert np.isclose(fidelity, 1)\n\n# before the fixes Bob's qubit alone is completely random\nqc = QuantumCircuit(3)\nqc.ry(1.0, 0)\nqc.h(1)\nqc.cx(1, 2)\nqc.cx(0, 1)\nqc.h(0)\nbob = partial_trace(Statevector(qc), [0, 1])\nprint(\"Bob before the fixes:\\n\", np.round(bob.data.real, 3))\nassert np.allclose(bob.data, np.eye(2) / 2)\n"
 },
 "31_bb84": {
  "file": "examples/31_bb84.py",
  "code": "\"\"\"Level 31, QUANTUM KEYS: BB84: a secret key, a spy.\n\nRun: python examples/31_bb84.py\n\"\"\"\nimport numpy as np\nfrom qiskit import QuantumCircuit\nfrom qiskit.primitives import StatevectorSampler\n\nN = 400\nrng = np.random.default_rng(2024)\nsampler = StatevectorSampler(seed=99)\n\n\ndef prepare(bit, basis):\n    \"\"\"A qubit holding `bit` in basis 0 (Z) or 1 (X).\"\"\"\n    qc = QuantumCircuit(1)\n    if bit:\n        qc.x(0)\n    if basis:\n        qc.h(0)\n    return qc\n\n\ndef measure(qcs, bases):\n    \"\"\"Read each qubit in its basis; one shot each.\"\"\"\n    pubs = []\n    for qc, basis in zip(qcs, bases):\n        qc = qc.copy()\n        if basis:\n            qc.h(0)\n        qc.measure_all()\n        pubs.append(qc)\n    res = sampler.run(pubs, shots=1).result()\n    return [int(next(iter(r.data.meas.get_counts())))\n            for r in res]\n\n\ndef run(eve):\n    bits = rng.integers(0, 2, N)\n    a_bases = rng.integers(0, 2, N)\n    b_bases = rng.integers(0, 2, N)\n    qubits = [prepare(b, a) for b, a in zip(bits, a_bases)]\n    if eve:  # Eve reads in random bases and resends\n        e_bases = rng.integers(0, 2, N)\n        e_bits = measure(qubits, e_bases)\n        qubits = [prepare(b, e)\n                  for b, e in zip(e_bits, e_bases)]\n    got = np.array(measure(qubits, b_bases))\n    keep = a_bases == b_bases          # compare bases only\n    errors = np.mean(got[keep] != bits[keep])\n    return keep.mean(), errors\n\n\nkept, err = run(eve=False)\nprint(f\"no spy:   kept {kept:.2f}, error rate {err:.3f}\")\nassert err == 0 and abs(kept - 0.5) < 0.1\nkept, err = run(eve=True)\nprint(f\"with Eve: kept {kept:.2f}, error rate {err:.3f}\")\nassert abs(err - 0.25) < 0.08\n"
 },
 "32_kickback": {
  "file": "examples/32_kickback.py",
  "code": "\"\"\"Level 32, PHASE KICKBACK: CNOT |+>|-> = |->|->.\n\nRun: python examples/32_kickback.py\n\"\"\"\nfrom qiskit import QuantumCircuit\nfrom qiskit.quantum_info import Statevector\n\nqc = QuantumCircuit(2)\nqc.h(0)              # control |+>\nqc.x(1)\nqc.h(1)              # target |->\nbefore = Statevector(qc)\nqc.cx(0, 1)\nafter = Statevector(qc)\n\n# labels are in Qiskit order: qubit 1 first, then qubit 0\nassert before.equiv(Statevector.from_label(\"-+\"))\nassert after.equiv(Statevector.from_label(\"--\"))\nprint(\"the control turned from |+> into |->\")\n\n# the puzzle: one more H turns q0 into |1>\nqc.h(0)\nassert Statevector(qc).equiv(Statevector.from_label(\"-1\"))\n"
 },
 "33_deutsch": {
  "file": "examples/33_deutsch.py",
  "code": "\"\"\"Level 33, DEUTSCH: constant or balanced, with one query.\n\nRun: python examples/33_deutsch.py\n\"\"\"\nfrom qiskit import QuantumCircuit\nfrom qiskit.quantum_info import Statevector\n\n\ndef oracle(f0, f1):\n    \"\"\"U_f |x>|y> = |x>|y XOR f(x)> for f(0)=f0, f(1)=f1.\"\"\"\n    qc = QuantumCircuit(2, name=\"U_f\")\n    if f0:\n        qc.x(1)       # f(0) = 1 flips y for x = 0 ...\n    if f0 != f1:\n        qc.cx(0, 1)   # ... and f(0) != f(1) flips it for x = 1\n    return qc\n\n\ndef deutsch(f0, f1):\n    qc = QuantumCircuit(2)\n    qc.x(1)\n    qc.h([0, 1])\n    qc.compose(oracle(f0, f1), inplace=True)  # ONE query\n    qc.h(0)\n    p1 = Statevector(qc).probabilities([0])[1]  # P(q0 = 1)\n    return round(p1)\n\n\nfor f0 in (0, 1):\n    for f1 in (0, 1):\n        kind = \"constant\" if f0 == f1 else \"balanced\"\n        got = deutsch(f0, f1)\n        print(f\"f(0)={f0} f(1)={f1}: {kind:8s} -> q0 = {got}\")\n        assert got == (f0 != f1)\n"
 },
 "34_dj": {
  "file": "examples/34_dj.py",
  "code": "\"\"\"Level 34, DEUTSCH-JOZSA: n-bit constant or balanced.\n\nRun: python examples/34_dj.py\n\"\"\"\nfrom itertools import combinations, product\n\nfrom qiskit import QuantumCircuit\nfrom qiskit.quantum_info import Statevector\n\nn = 3\n\n\ndef oracle(table):\n    \"\"\"U_f for any f given as a truth table of 2**n bits.\"\"\"\n    qc = QuantumCircuit(n + 1)\n    for x, fx in enumerate(table):\n        if not fx:\n            continue\n        bits = [(x >> q) & 1 for q in range(n)]\n        zeros = [q for q in range(n) if not bits[q]]\n        if zeros:\n            qc.x(zeros)\n        qc.mcx(list(range(n)), n)   # flip y when the input is x\n        if zeros:\n            qc.x(zeros)\n    return qc\n\n\ndef dj(table):\n    qc = QuantumCircuit(n + 1)\n    qc.x(n)\n    qc.h(range(n + 1))\n    qc.compose(oracle(table), inplace=True)\n    qc.h(range(n))\n    p = Statevector(qc).probabilities(list(range(n)))\n    return \"constant\" if p[0] > 0.999 else \"balanced\"\n\n\ntests = [[0] * 8, [1] * 8]                      # constant\nfor ones in list(combinations(range(8), 4))[:6]:  # balanced\n    tests.append([int(x in ones) for x in range(8)])\nfor table in tests:\n    want = \"constant\" if len(set(table)) == 1 else \"balanced\"\n    got = dj(table)\n    print(table, \"->\", got)\n    assert got == want\n"
 },
 "35_bv": {
  "file": "examples/35_bv.py",
  "code": "\"\"\"Level 35, BERNSTEIN-VAZIRANI: read a secret in one query.\n\nRun: python examples/35_bv.py\n\"\"\"\nfrom qiskit import QuantumCircuit\nfrom qiskit.quantum_info import Statevector\n\nsecret = \"1011\"          # s, written as qubits 0, 1, 2, 3\nn = len(secret)\n\nqc = QuantumCircuit(n + 1)\nqc.x(n)\nqc.h(range(n + 1))\nfor q, bit in enumerate(secret):    # f(x) = s.x mod 2\n    if bit == \"1\":\n        qc.cx(q, n)\nqc.h(range(n))\n\nprobs = Statevector(qc).probabilities_dict(list(range(n)))\n(key,) = [k for k, p in probs.items() if p > 0.999]\nfound = key[::-1]  # Qiskit writes qubit 0 last\nprint(\"secret\", secret, \"found\", found)\nassert found == secret\n"
 },
 "36_simon": {
  "file": "examples/36_simon.py",
  "code": "\"\"\"Level 36, SIMON: find a hidden XOR period s.\n\nRun: python examples/36_simon.py\n\"\"\"\nfrom itertools import product\n\nfrom qiskit import QuantumCircuit\nfrom qiskit.primitives import StatevectorSampler\n\nn = 3\nsecret = \"110\"   # s as bits for qubits 0, 1, 2\ns = [int(b) for b in secret]\n\n\ndef oracle():\n    \"\"\"|x>|0> -> |x>|f(x)> with f(x) = f(x XOR s):\n    copy x, then XOR s into the output when x_k = 1 for the\n    first k with s_k = 1.\"\"\"\n    qc = QuantumCircuit(2 * n)\n    for q in range(n):\n        qc.cx(q, n + q)\n    k = s.index(1)\n    for q in range(n):\n        if s[q]:\n            qc.cx(k, n + q)\n    return qc\n\n\nqc = QuantumCircuit(2 * n, n)\nqc.h(range(n))\nqc.compose(oracle(), inplace=True)\nqc.h(range(n))\nqc.measure(range(n), range(n))\nres = StatevectorSampler(seed=3).run([qc], shots=64).result()\n# reversed: qubit 0 first\nys = [k[::-1] for k in res[0].data.c.get_counts()]\nprint(\"measured y:\", sorted(ys))\n\n\ndef dot(a, b):\n    return sum(int(x) * int(y) for x, y in zip(a, b)) % 2\n\n\n# every y satisfies y.s = 0 (mod 2)\nassert all(dot(y, secret) == 0 for y in ys)\n# the only nonzero s consistent with all of them is the secret\ncands = []\nfor c in product(\"01\", repeat=n):\n    c = \"\".join(c)\n    if \"1\" in c and all(dot(y, c) == 0 for y in ys):\n        cands.append(c)\nprint(\"candidates for s:\", cands)\nassert cands == [secret]\n"
 },
 "37_grover": {
  "file": "examples/37_grover.py",
  "code": "\"\"\"Level 37, GROVER SEARCH: 1 marked item among 8.\n\nRun: python examples/37_grover.py\n\"\"\"\nimport numpy as np\nfrom qiskit import QuantumCircuit\nfrom qiskit.quantum_info import Statevector\n\nn = 3\nmarked = \"101\"   # in Qiskit order (qubit 2 first)\n\n\ndef oracle():\n    qc = QuantumCircuit(n)\n    zeros = [q for q in range(n) if marked[::-1][q] == \"0\"]\n    qc.x(zeros)\n    qc.h(n - 1)\n    qc.mcx(list(range(n - 1)), n - 1)   # a multi-controlled Z\n    qc.h(n - 1)\n    qc.x(zeros)\n    return qc\n\n\ndef diffuser():\n    qc = QuantumCircuit(n)\n    qc.h(range(n))\n    qc.x(range(n))\n    qc.h(n - 1)\n    qc.mcx(list(range(n - 1)), n - 1)\n    qc.h(n - 1)\n    qc.x(range(n))\n    qc.h(range(n))\n    return qc\n\n\nrounds = int(np.floor(np.pi / 4 * np.sqrt(2**n)))\nqc = QuantumCircuit(n)\nqc.h(range(n))\nfor r in range(rounds):\n    qc.compose(oracle(), inplace=True)\n    qc.compose(diffuser(), inplace=True)\n    p = Statevector(qc).probabilities_dict()[marked]\n    print(f\"after round {r + 1}: P({marked}) = {p:.3f}\")\nassert rounds == 2\nassert p > 0.94\n"
 },
 "38_qft": {
  "file": "examples/38_qft.py",
  "code": "\"\"\"Level 38, FOURIER TRANSFORM: build the QFT, check it.\n\nRun: python examples/38_qft.py\n\"\"\"\nimport numpy as np\nfrom qiskit import QuantumCircuit\nfrom qiskit.circuit.library import QFTGate\nfrom qiskit.quantum_info import Operator, Statevector\n\n\ndef qft(n):\n    \"\"\"The textbook circuit: H, controlled phase turns,\n    then reverse the qubit order. Qiskit's qubit n-1 is\n    the high bit.\"\"\"\n    qc = QuantumCircuit(n)\n    for j in reversed(range(n)):\n        qc.h(j)\n        for k in reversed(range(j)):\n            qc.cp(np.pi / 2 ** (j - k), k, j)\n    for q in range(n // 2):\n        qc.swap(q, n - 1 - q)\n    return qc\n\n\nn = 3\nN = 2**n\nw = np.exp(2j * np.pi / N)\ndft = np.array([[w ** (j * k) for j in range(N)]\n                for k in range(N)]) / np.sqrt(N)\nassert Operator(qft(n)).equiv(Operator(dft))\nassert Operator(QFTGate(n)).equiv(Operator(dft))\nprint(\"our circuit = QFTGate = the DFT matrix\")\n\n# the puzzle (2 qubits): QFT|01>, |01> meaning x = 1\ntwo = QuantumCircuit(2)\ntwo.x(0)               # x = 1 in Qiskit's order\ntwo.compose(qft(2), inplace=True)\nwant = np.array([1, 1j, -1, -1j]) / 2\nprint(np.round(Statevector(two).data, 3))\nassert Statevector(two).equiv(Statevector(want))\n"
 },
 "39_qpe": {
  "file": "examples/39_qpe.py",
  "code": "\"\"\"Level 39, PHASE ESTIMATION: read the phase of T.\n\nT|1> = e^(2 pi i / 8)|1>, so phi = 1/8 = 0.001 in binary.\nRun: python examples/39_qpe.py\n\"\"\"\nimport numpy as np\nfrom qiskit import QuantumCircuit\nfrom qiskit.circuit.library import QFTGate\nfrom qiskit.quantum_info import Statevector\n\nt = 3                       # counting qubits 0 .. t-1\nqc = QuantumCircuit(t + 1)\nqc.x(t)                     # the eigenvector |1>\nqc.h(range(t))\nfor k in range(t):          # qubit k controls U^(2^k)\n    qc.cp(2 * np.pi / 8 * 2**k, k, t)\nqc.append(QFTGate(t).inverse(), range(t))\n\nprobs = Statevector(qc).probabilities_dict(list(range(t)))\nbest = max(probs, key=probs.get)\nphi = int(best, 2) / 2**t   # the key is read as a binary number\nprint(\"counting register:\", best, \" phi =\", phi)\nassert np.isclose(probs[best], 1)\nassert phi == 1 / 8\n\n# the game's puzzle: U = S (phi = 1/4) with 2 counting qubits\nqc = QuantumCircuit(3)\nqc.x(2)\nqc.h([0, 1])\nfor k in range(2):\n    qc.cp(np.pi / 2 * 2**k, k, 2)\nqc.append(QFTGate(2).inverse(), [0, 1])\nprobs = Statevector(qc).probabilities_dict([0, 1])\nprint(\"S: counting register\", max(probs, key=probs.get))\nassert np.isclose(probs[\"01\"], 1)   # 0.01 binary = 1/4\n"
 },
 "40_shor": {
  "file": "examples/40_shor.py",
  "code": "\"\"\"Level 40, SHOR FACTORING: factor 15 with a = 7.\n\nThe quantum part is phase estimation of \"multiply by 7\nmod 15\"; continued fractions turn the phase into r.\nRun: python examples/40_shor.py  (takes a few seconds)\n\"\"\"\nfrom fractions import Fraction\nfrom math import gcd\n\nimport numpy as np\nfrom qiskit import QuantumCircuit\nfrom qiskit.circuit.library import QFTGate, UnitaryGate\nfrom qiskit.quantum_info import Statevector\n\nN, a = 15, 7\nt, m = 8, 4          # 8 counting qubits, 4 work qubits\n\n\ndef mult_gate(factor):\n    \"\"\"|y> -> |factor*y mod N> for y < N, as a 16x16\n    permutation matrix (y = 15 is left alone).\"\"\"\n    U = np.zeros((16, 16))\n    for y in range(16):\n        U[factor * y % N if y < N else y, y] = 1\n    return UnitaryGate(U, label=f\"x{factor}\")\n\n\nqc = QuantumCircuit(t + m)\nqc.h(range(t))\nqc.x(t)              # work register starts at y = 1\nfor k in range(t):   # counting qubit k controls U^(2^k)\n    power = pow(a, 2**k, N)\n    qc.append(mult_gate(power).control(1),\n              [k] + list(range(t, t + m)))\nqc.append(QFTGate(t).inverse(), range(t))\n\nprobs = Statevector(qc).probabilities_dict(list(range(t)))\npeaks = sorted(k for k, p in probs.items() if p > 0.01)\nprint(\"peaks:\", [int(k, 2) for k in peaks])\n\nfound = set()\nfor key in peaks:\n    phase = Fraction(int(key, 2), 2**t)\n    r = phase.limit_denominator(N).denominator\n    if pow(a, r, N) == 1:\n        found.add(r)\nr = min(found)\nprint(\"period r =\", r)\nassert r == 4\nx = pow(a, r // 2, N)\nfactors = sorted({gcd(x - 1, N), gcd(x + 1, N)})\nprint(\"factors of 15:\", factors)\nassert factors == [3, 5]\n"
 },
 "41_noise": {
  "file": "examples/41_noise.py",
  "code": "\"\"\"Level 41, NOISE: decoherence shrinks the Bloch arrow.\n\nRun: python examples/41_noise.py\n\"\"\"\nimport numpy as np\nfrom qiskit.quantum_info import (DensityMatrix, Kraus,\n                                 SparsePauliOp)\n\np = 0.1   # a dephasing channel: Z happens with chance p\ndephase = Kraus([np.sqrt(1 - p) * np.eye(2),\n                 np.sqrt(p) * np.diag([1, -1])])\n\nrho = DensityMatrix.from_label(\"+\")\nfor step in range(6):\n    x = rho.expectation_value(SparsePauliOp(\"X\")).real\n    purity = rho.purity().real\n    print(f\"step {step}: <X> = {x:.3f} purity {purity:.3f}\")\n    rho = rho.evolve(dephase)\n# each step multiplies <X> by (1 - 2p)\nassert np.isclose(x, (1 - 2 * p) ** 5)\n\n# fully dephased |+> is the fully mixed state I/2\nfull = Kraus([np.sqrt(0.5) * np.eye(2),\n              np.sqrt(0.5) * np.diag([1, -1])])\nmixed = DensityMatrix.from_label(\"+\").evolve(full)\nassert np.allclose(mixed.data, np.eye(2) / 2)\n\nprint(\"100 gates at 99% each:\", round(0.99**100, 3))\n"
 },
 "42_qec": {
  "file": "examples/42_qec.py",
  "code": "\"\"\"Level 42, ERROR CORRECTION: the 3-qubit bit-flip code.\n\nRun: python examples/42_qec.py\n\"\"\"\nimport numpy as np\nfrom qiskit import QuantumCircuit\nfrom qiskit.quantum_info import (DensityMatrix, Statevector,\n                                 partial_trace)\n\npsi = QuantumCircuit(1)       # the puzzle's state: H T H |0>\npsi.h(0)\npsi.t(0)\npsi.h(0)\nwant = DensityMatrix(psi)\n\nfor error in (None, 0, 1, 2):\n    qc = QuantumCircuit(3)\n    qc.compose(psi, [0], inplace=True)\n    qc.cx(0, 1)               # encode: a|000> + b|111>\n    qc.cx(0, 2)\n    if error is not None:\n        qc.x(error)           # one bit flip\n    qc.cx(0, 1)               # decode: q1, q2 = syndrome\n    qc.cx(0, 2)\n    qc.ccx(1, 2, 0)           # both 1: q0 was hit, flip it\n    got = partial_trace(Statevector(qc), [1, 2])\n    ok = np.allclose(got.data, want.data)\n    print(f\"error on {error}: q0 restored = {ok}\")\n    assert ok\n"
 },
 "43_variational": {
  "file": "examples/43_variational.py",
  "code": "\"\"\"Level 43, VARIATIONAL ALGORITHMS: a tiny VQE.\n\nRun: python examples/43_variational.py\n\"\"\"\nimport numpy as np\nfrom qiskit import QuantumCircuit\nfrom qiskit.quantum_info import SparsePauliOp, Statevector\nfrom scipy.optimize import minimize\n\n# 1 qubit, H = Z: the lowest energy -1 is at theta = pi (|1>)\ndef energy1(theta):\n    qc = QuantumCircuit(1)\n    qc.ry(theta[0], 0)\n    return Statevector(qc).expectation_value(\n        SparsePauliOp(\"Z\")).real\n\n\nres = minimize(energy1, x0=[0.3], method=\"COBYLA\")\nprint(\"H = Z: theta =\", round(res.x[0], 3),\n      \"E =\", round(res.fun, 4))\nassert np.isclose(res.fun, -1, atol=1e-3)\n\n# 2 qubits, H = ZZ + 0.5 XI, against the exact answer\nH = SparsePauliOp([\"ZZ\", \"XI\"], [1.0, 0.5])\nexact = np.linalg.eigvalsh(H.to_matrix()).min()\n\n\ndef energy2(p):\n    qc = QuantumCircuit(2)\n    qc.ry(p[0], 0)\n    qc.ry(p[1], 1)\n    qc.cx(0, 1)\n    qc.ry(p[2], 0)\n    qc.ry(p[3], 1)\n    return Statevector(qc).expectation_value(H).real\n\n\nrng = np.random.default_rng(0)\nbest = min((minimize(energy2, rng.uniform(0, 2 * np.pi, 4),\n                     method=\"COBYLA\") for _ in range(5)),\n           key=lambda r: r.fun)\nprint(\"VQE energy\", round(best.fun, 5),\n      \" exact\", round(exact, 5))\nassert abs(best.fun - exact) < 1e-3\n"
 },
 "44_qiskit": {
  "file": "examples/44_qiskit.py",
  "code": "\"\"\"Level 44, QISKIT IN PRACTICE: order, counts, transpile.\n\nRun: python examples/44_qiskit.py\n\"\"\"\nfrom qiskit import QuantumCircuit, transpile\nfrom qiskit.primitives import StatevectorSampler\nfrom qiskit.quantum_info import Operator, Statevector\n\n# qubit 0 is the RIGHTMOST character of a key\nqc = QuantumCircuit(3)\nqc.x(0)\nqc.measure_all()\nres = StatevectorSampler(seed=1).run([qc], shots=100).result()\ncounts = res[0].data.meas.get_counts()\nprint(\"X on qubit 0 of 3:\", counts)\nassert counts == {\"001\": 100}\n\n# a GHZ state, drawn and simulated\nghz = QuantumCircuit(3)\nghz.h(0)\nghz.cx(0, 1)\nghz.cx(1, 2)\nprint(ghz.draw())\nprint(Statevector(ghz).probabilities_dict())\n\n# rewrite it for a machine with only rz, sx, x and cx\nhw = transpile(ghz, basis_gates=[\"rz\", \"sx\", \"x\", \"cx\"],\n               optimization_level=1)\nprint(hw.draw())\nprint(\"gates:\", dict(hw.count_ops()))\nassert set(hw.count_ops()) <= {\"rz\", \"sx\", \"x\", \"cx\"}\nassert Operator(hw).equiv(Operator(ghz))\n\n# On real IBM hardware you would use qiskit-ibm-runtime:\n#   from qiskit_ibm_runtime import QiskitRuntimeService\n#   from qiskit_ibm_runtime import SamplerV2\n# with an account; see the Qiskit documentation.\n"
 },
 "45_beyond": {
  "file": "examples/45_beyond.py",
  "code": "\"\"\"Level 45, WHAT NEXT: a playground. Change it and rerun!\n\nRun: python examples/45_beyond.py\n\"\"\"\nfrom qiskit import QuantumCircuit\nfrom qiskit.primitives import StatevectorSampler\nfrom qiskit.quantum_info import Statevector\n\nqc = QuantumCircuit(3)\nqc.h(0)          # try: qc.x(0), qc.s(1), qc.ccx(0, 1, 2) ...\nqc.cx(0, 1)\nqc.cx(0, 2)\nprint(qc.draw())\n\nstate = Statevector(qc)\nprint(\"amplitudes (Qiskit order):\")\nfor key, amp in state.to_dict().items():\n    print(f\"  |{key}>  {amp:.3f}\")\n\nqc.measure_all()\nres = StatevectorSampler(seed=0).run([qc], shots=1000).result()\ncounts = res[0].data.meas.get_counts()\nprint(\"1000 shots:\", counts)\nassert set(counts) == {\"000\", \"111\"}\n"
 }
};
